<script setup>
import {computed,onMounted,ref} from 'vue';import {get,pct} from '../api/client';import DataTable from '../components/DataTable.vue';import StockHistoryModal from '../components/StockHistoryModal.vue';
const modelNames={multi_factor_rank:'次日方向模型',tradeable_t1_open:'T+1可交易模型'},runs=ref([]),activeModel=ref('multi_factor_rank'),selected=ref({}),data=ref({groups:[],detail:[]}),historyStock=ref(null);const modelRuns=computed(()=>runs.value.filter(r=>r.model_code===activeModel.value));const isTradeable=computed(()=>activeModel.value==='tradeable_t1_open');async function load(){const id=selected.value[activeModel.value];data.value=id?await get(`/intraday/${id}`):{groups:[],detail:[]}}async function switchModel(code){activeModel.value=code;await load()}onMounted(async()=>{runs.value=await get('/intraday');for(const code of Object.keys(modelNames))selected.value[code]=runs.value.find(r=>r.model_code===code)?.id;await load()});
const groups=[{label:'TopN',key:'top_n'},{label:'有效数',key:'valid_count'},{label:'上涨数',key:'up_count'},{label:'上涨比例',key:'up_rate',format:pct},{label:'平均收益',key:'avg_return',format:pct},{label:'超额收益',key:'excess_return',format:pct}];const detail=computed(()=>[{label:'排名',key:'ranking'},{label:'代码',key:'stock_code',action:r=>historyStock.value=r},{label:'市场',key:'market'},{label:'名称',key:'stock_name'},{label:'评分',key:'score'},{label:isTradeable.value?'模拟开盘买入价':'信号日收盘参考价',key:'previous_close'},{label:'最新价',key:'current_price'},{label:isTradeable.value?'持仓浮盈亏':'盘中方向收益',key:'current_return',format:pct},{label:'超额收益',key:'market_excess',format:pct}]);
</script><template><div class="model-tabs"><button v-for="(name,code) in modelNames" :class="{active:activeModel===code}" @click="switchModel(code)">{{name}}</button></div><select v-if="modelRuns.length" v-model="selected[activeModel]" @change="load"><option v-for="r in modelRuns" :value="r.id">{{r.observed_at}} · 信号日 {{r.base_date}}</option></select><div v-else class="empty compact-empty">该模型暂无盘中记录</div><div class="experimental-note"><template v-if="isTradeable">从当日开盘模拟买入价计算到当前价，仅表示T+1持仓浮盈亏，当天不能卖出。</template><template v-else>从信号日收盘价计算到当前价，用于观察次日方向，不代表实际开盘买入收益。</template></div><template v-if="modelRuns.length"><div class="section"><h2>{{modelNames[activeModel]}} TopN表现</h2><DataTable :columns="groups" :rows="data.groups"/></div><div class="section"><h2>{{modelNames[activeModel]}}候选明细</h2><DataTable :columns="detail" :rows="data.detail"/></div></template><StockHistoryModal :stock="historyStock" @close="historyStock=null"/></template>
